import React, { useState, useEffect } from "react";
import { adminService } from "../services/adminService";
import { Bike, Search, MapPin } from "lucide-react";
import toast from "react-hot-toast";
import {
  DATE_FILTER_LABELS,
  DATE_FILTER_OPTIONS,
  getDateFilterParams,
} from "../components/AdminDateFilter";

const RidersDistance = () => {
  const [riders, setRiders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterType, setFilterType] = useState("all");
  const [customStartDate, setCustomStartDate] = useState("");
  const [customEndDate, setCustomEndDate] = useState("");

  const fetchRidersDistance = async () => {
    try {
      setLoading(true);
      const { startDate, endDate } = getDateFilterParams(
        filterType,
        customStartDate,
        customEndDate
      );

      const params = {};
      if (startDate) params.startDate = startDate;
      if (endDate) params.endDate = endDate;

      const data = await adminService.getRidersDistance(params);
      setRiders(data);
    } catch (error) {
      console.error(error);
      toast.error("Failed to load riders distance data");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRidersDistance();
  }, [filterType, customStartDate, customEndDate]);

  const filteredRiders = riders.filter((rider) =>
    rider.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    rider.phone?.includes(searchTerm)
  );

  return (
    <div className="content-area animate-fade-in">
      <div className="page-header">
        <div className="page-title-group">
          <h2>Riders Distance</h2>
          <span className="subtitle">
            Total distance covered by verified riders across Orders, Custom Orders, and Rides
          </span>
        </div>
        <div className="header-actions">
          <div className="search-bar">
            <Search size={20} />
            <input
              type="text"
              placeholder="Search riders by name or phone..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
      </div>

      <div
        className="glass-panel dashboard-filters"
        style={{
          marginBottom: "1.5rem",
          padding: "1rem",
          display: "flex",
          flexWrap: "wrap",
          gap: "0.75rem",
          alignItems: "center",
          borderRadius: "12px",
        }}
      >
        {DATE_FILTER_OPTIONS.map((option) => (
          <button
            key={option.id}
            onClick={() => setFilterType(option.id)}
            style={{
              padding: "0.5rem 1rem",
              borderRadius: "8px",
              border: "none",
              background:
                filterType === option.id
                  ? "var(--accent-primary)"
                  : "rgba(255, 255, 255, 0.05)",
              color: filterType === option.id ? "white" : "var(--text-muted)",
              fontWeight: 500,
              fontSize: "0.875rem",
              cursor: "pointer",
              transition: "all 0.2s ease",
            }}
            onMouseEnter={(e) => {
              if (filterType !== option.id) {
                e.target.style.background = "rgba(255, 255, 255, 0.1)";
              }
            }}
            onMouseLeave={(e) => {
              if (filterType !== option.id) {
                e.target.style.background = "rgba(255, 255, 255, 0.05)";
              }
            }}
          >
            {option.label}
          </button>
        ))}

        {filterType === "custom" && (
          <div
            style={{
              display: "flex",
              gap: "0.75rem",
              flexWrap: "wrap",
              marginTop: "0.5rem",
            }}
          >
            <div style={{ display: "flex", flexDirection: "column", gap: "0.25rem" }}>
              <label style={{ fontSize: "0.75rem", color: "var(--text-muted)" }}>From Date</label>
              <input
                type="date"
                value={customStartDate}
                onChange={(e) => setCustomStartDate(e.target.value)}
                style={{
                  padding: "0.5rem 0.75rem",
                  borderRadius: "8px",
                  border: "1px solid rgba(255, 255, 255, 0.1)",
                  background: "var(--surface-color)",
                  color: "var(--text-primary)",
                  fontSize: "0.875rem",
                }}
              />
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: "0.25rem" }}>
              <label style={{ fontSize: "0.75rem", color: "var(--text-muted)" }}>To Date</label>
              <input
                type="date"
                value={customEndDate}
                onChange={(e) => setCustomEndDate(e.target.value)}
                style={{
                  padding: "0.5rem 0.75rem",
                  borderRadius: "8px",
                  border: "1px solid rgba(255, 255, 255, 0.1)",
                  background: "var(--surface-color)",
                  color: "var(--text-primary)",
                  fontSize: "0.875rem",
                }}
              />
            </div>
          </div>
        )}
      </div>

      <div className="table-container">
        {loading ? (
          <div className="table-loader" style={{ padding: '3rem' }}>Loading Riders Distance...</div>
        ) : (
          <table className="data-table">
            <thead>
              <tr>
                <th>Rider Info</th>
                <th>Status</th>
                <th>Total Distance Covered (km)</th>
              </tr>
            </thead>
            <tbody>
              {filteredRiders.map((rider) => (
                <tr key={rider._id}>
                  <td>
                    <div className="user-info-cell" style={{ gap: '16px' }}>
                      <div className="user-avatar" style={{ flexShrink: 0 }}>
                        <Bike size={20} />
                      </div>
                      <div className="user-details" style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                        <span className="user-name" style={{ fontSize: '15px', fontWeight: '600', color: 'var(--text-primary)' }}>
                          {rider.name || "N/A"}
                        </span>
                        <span className="user-phone" style={{ fontSize: '13px', color: 'var(--text-muted)' }}>
                          {rider.phone}
                        </span>
                        {rider.city && (
                          <span className="user-email" style={{ display: 'flex', alignItems: 'center', gap: '4px', marginTop: '2px', color: 'var(--text-muted)', fontSize: '12px' }}>
                            <MapPin size={12} /> {rider.city}
                          </span>
                        )}
                      </div>
                    </div>
                  </td>
                  <td>
                    <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                      <span className="status-badge completed">Verified</span>
                      <span className={`status-badge ${rider.isOnline ? "active" : "inactive"}`}>
                        {rider.isOnline ? "Online" : "Offline"}
                      </span>
                    </div>
                  </td>
                  <td>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <div
                        style={{
                          padding: '8px 16px',
                          background: 'rgba(59, 130, 246, 0.1)',
                          color: 'var(--accent-primary)',
                          borderRadius: '8px',
                          fontWeight: '700',
                          fontSize: '15px'
                        }}
                      >
                        {rider.totalDistance.toFixed(2)} km
                      </div>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredRiders.length === 0 && (
                <tr>
                  <td colSpan="3" className="empty-state" style={{ padding: '3rem' }}>
                    No verified riders found
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default RidersDistance;
